const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={rooms:[],sources:[]},selected=location.hash.slice(1),tab='conversation',view='requests',filter='all',token=sessionStorage.getItem('accord-token'),user=JSON.parse(sessionStorage.getItem('accord-user')||'null');let draft='',busy=false;
const room=()=>state.rooms.find(r=>r.id===selected);const joined=()=>room()?.participants.some(p=>p.id===user?.id);const helperName=()=>user?.department==='Business'?'Maya':'Theo';
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}function modal(h){$('#modal-content').innerHTML=h;$('#modal').showModal()}
async function api(action,data={}){const res=await fetch('/api/'+action,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({roomId:selected,...data})});const result=await res.json();if(!res.ok){if(res.status===401){token=null;user=null;sessionStorage.clear();identity()}throw Error(result.error)}return result}
async function action(name,data={}){if(busy)return;busy=true;try{await api(name,data);await refresh()}catch(e){toast(e.message)}finally{busy=false}}
async function refresh(){const res=await fetch('/api/state');if(!res.ok)throw Error('Unable to load workspace');state=await res.json();if(!room())selected=state.rooms[0]?.id||'';render()}
function identity(){modal(`<div class="eyebrow">JOIN THE SHARED WORKSPACE</div><h2>Your team. Your helper.</h2><p>Join as a department member. Your helper advises you; you contribute context and approve for your department.</p><form id="identity-form"><label for="name">Your name</label><input id="name" required maxlength="60" value="${esc(user?.name||'')}" placeholder="Jamie Davis"><label for="department">Department</label><select id="department"><option>Business</option><option>Engineering</option></select><p>Maya helps Business with customer needs and commercial goals. Theo helps Engineering with capacity and delivery tradeoffs.</p><button class="primary">Enter workspace →</button></form><div class="boundary">Hackathon workspace: department selection is self-declared, not authenticated. Use sample information only.</div>`);if(user)$('#department').value=user.department;$('#identity-form').onsubmit=async e=>{e.preventDefault();try{const result=await api('session',{name:$('#name').value,department:$('#department').value});token=result.token;user=result.user;sessionStorage.setItem('accord-token',token);sessionStorage.setItem('accord-user',JSON.stringify(user));$('#modal').close();await action('join')}catch(e){toast(e.message)}}}
function render(){const r=room();$('#active-stat').textContent=state.rooms.filter(r=>r.status!=='Approved').length;$('#agreement-stat').textContent=state.rooms.filter(r=>r.status==='Approved').length;$('#request-count').textContent=state.rooms.length;$('#list-count').textContent=state.rooms.length;$('#reset').textContent=user?`${user.name} · ${user.department} ⌄`:'Join workspace';$('.workspace-sub').innerHTML='<i></i> Shared server workspace';$('.profile').innerHTML=`<span class="avatar human">${esc((user?.name||'?').slice(0,2).toUpperCase())}</span><div>${esc(user?.name||'Guest')}<small>${esc(user?.department||'Choose a department')}</small></div>`;$('#breadcrumb').innerHTML='Workspace <span>/</span> '+(view==='sources'?'Knowledge sources':view==='agreements'?'Agreements':'Live negotiations');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let rooms=state.rooms.filter(r=>(view!=='agreements'||r.status==='Approved')&&(filter==='all'||(filter==='done'?r.status==='Approved':r.status!=='Approved')));$('#request-items').innerHTML=rooms.map(x=>`<button class="request-card ${x.id===selected?'selected':''}" data-room="${x.id}"><div class="request-meta"><span>${x.participants.length} joined</span><span class="pill ${x.status==='Approved'?'done':'review'}">${x.status}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><div class="request-teams">Business ⇄ Engineering · ${x.messages.length} updates</div></button>`).join('')||'<div class="empty">No negotiations in this view.</div>';document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{draft=$('#comment')?.value||'';selected=b.dataset.room;location.hash=selected;draft='';tab='conversation';render()});if(view==='sources'){renderSources();return}if(!r){$('#detail').innerHTML='<div class="empty">Create a negotiation to get started.</div>';return}const isJoined=joined();$('#detail').innerHTML=`<div class="detail-heading"><div class="detail-topline"><span>LIVE NEGOTIATION · REVISION ${r.revision}</span><span class="pill ${r.status==='Approved'?'done':'review'}">${r.status}</span></div><h2>${esc(r.title)}</h2><div class="detail-description">${esc(r.description)}</div><div class="participant-row"><span>${r.participants.length} team members joined · Maya & Theo assisting</span><button class="outline" id="invite" style="margin-left:auto">Copy room link</button></div><div class="members">${r.participants.map(p=>`<span class="member ${p.department==='Business'?'business':'engineering'}">${esc(p.name)} · ${p.department}</span>`).join('')||'<span>No team members yet. Be the first to join.</span>'}</div>${!isJoined?'<button class="primary" id="join-room" style="margin-top:15px">Join this negotiation</button>':`<div class="helper-bar"><span class="avatar ${user.department==='Business'?'business':'engineering'}">${helperName()[0]}</span><span><strong>${helperName()} is your ${user.department} helper</strong><small>Advises on your department’s evidence. You steer and approve.</small></span><button class="outline" id="ask-helper">Ask ${helperName()}</button></div>`}</div><div class="detail-tabs"><button data-tab="conversation" class="${tab==='conversation'?'active':''}">Live conversation <b>${r.messages.length}</b></button><button data-tab="agreement" class="${tab==='agreement'?'active':''}">Agreement <b>${r.revision}</b></button><button data-tab="evidence" class="${tab==='evidence'?'active':''}">Evidence</button></div><div id="tab-content"></div>`;$('#invite').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/#'+r.id);toast('Room link copied. Open it in another browser to join.')}catch{modal(`<h2>Invite your teammate</h2><p>Share this link. They must be able to reach the same server.</p><input readonly value="${esc(location.origin+'/#'+r.id)}">`)}};if($('#join-room'))$('#join-room').onclick=()=>user?action('join'):identity();if($('#ask-helper'))$('#ask-helper').onclick=()=>action('helper');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{draft=$('#comment')?.value||draft;tab=b.dataset.tab;render()});if(tab==='agreement')agreement();else if(tab==='evidence')renderSources(true);else conversation();}
function conversation(){const r=room();$('#tab-content').innerHTML='<div class="thread"><div class="date-line">Shared live session · Department helpers use sample evidence</div>'+r.messages.map(m=>m.type==='system'?`<div class="system-line">${esc(m.name==='Accord'?m.text:m.name+' · '+m.department+' '+m.text)}</div>`:`<div class="message"><span class="avatar ${m.type==='helper'?(m.department==='Business'?'business':'engineering'):'human'}">${esc(m.name.slice(0,2))}</span><div class="message-body"><div class="message-name">${esc(m.name)}<span class="agent-tag">${esc(m.department)} ${m.type==='helper'?'helper':m.type==='redirect'?'· new constraint':''}</span><span class="time">${new Date(m.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span></div><p>${esc(m.text)}</p>${m.refs.map(id=>`<button class="citation" data-source="${id}">▧ ${esc(state.sources.find(s=>s.id===id)?.title)}</button>`).join('')}</div></div>`).join('')+(r.proposal?`<div class="agreement-preview"><div class="label">SHARED DRAFT · REVISION ${r.revision}</div><h3>${esc(r.proposal.scope)}</h3><p>${esc(r.proposal.target)}<br>${esc(r.proposal.tradeoff)}</p><button class="primary" id="review">Review & approve →</button></div>`:'')+'</div>'+(joined()?`<form class="composer" id="comment-form"><textarea id="comment" required maxlength="2000" aria-label="Shared message" placeholder="Add context, or give your helper a new constraint…">${esc(draft)}</textarea><div class="composer-bottom"><select id="message-mode" aria-label="Message action" style="width:auto;font-size:10px;padding:5px"><option value="message">Post to conversation</option><option value="redirect">Redirect helpers & revise proposal</option></select><button type="submit">Send ↑</button></div></form>`:'<div class="empty">Join this negotiation to contribute context, ask your helper, or approve.</div>');if($('#review'))$('#review').onclick=()=>{tab='agreement';render()};if($('#comment'))$('#comment').oninput=e=>draft=e.target.value;if($('#comment-form'))$('#comment-form').onsubmit=async e=>{e.preventDefault();const text=$('#comment').value.trim(),mode=$('#message-mode').value;if(!text)return;try{await api(mode,{text});draft='';await refresh();toast(mode==='redirect'?'Proposal revised. Both departments must approve again.':'Message shared with everyone.')}catch(e){toast(e.message)}};bindSources()}
function agreement(){const r=room(),p=r.proposal;if(!p){$('#tab-content').innerHTML='<div class="empty">Join and ask your department helper to prepare a shared draft.</div>';return}$('#tab-content').innerHTML=`<div class="content-panel"><div class="eyebrow">SHARED PROPOSAL · REVISION ${r.revision}</div><h3 style="margin-top:12px">People decide. Helpers support.</h3><div class="agreement-grid">${[['Scope',p.scope],['Target',p.target],['Business value',p.businessValue],['Tradeoff',p.tradeoff]].map(([k,v])=>`<div><small>${k.toUpperCase()}</small><strong>${esc(v)}</strong></div>`).join('')}</div><h3>Owners & conditions</h3><p>${esc(p.owners)}<br>${esc(p.conditions)}</p><div class="boundary">${esc(p.capacity)}</div><h3 style="margin-top:20px">Team constraints to review</h3><p>${p.constraints.length?p.constraints.map(esc).join('<br>'):'No additional constraints submitted.'}</p><h3>Department approvals</h3>${['Business','Engineering'].map(d=>`<div class="approval-row"><strong>${d}</strong><span>${r.approvals[d]?'✓ '+esc(r.approvals[d].name)+' approved revision '+r.revision:'Awaiting a department member'}</span></div>`).join('')}${joined()?`<div class="actions"><button class="primary" id="approve" ${r.approvals[user.department]?'disabled':''}>Approve for ${user.department}</button><button class="outline" id="revise">Add constraint / request revision</button></div>`:''}<p style="font-size:10px">Each self-declared department approves separately. Any revised draft clears previous approvals. This demo records team alignment, not a contractual signature.</p></div>`;if($('#approve'))$('#approve').onclick=()=>action('approve',{revision:r.revision});if($('#revise'))$('#revise').onclick=()=>{tab='conversation';render();$('#message-mode').value='redirect';$('#comment').focus()}}
function bindSources(){document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{const s=state.sources.find(s=>s.id===b.dataset.source);modal(`<div class="eyebrow">${esc(s.department)} · SHARED SAMPLE EXCERPT</div><h2>${esc(s.title)}</h2><div class="quote">${esc(s.excerpt)}</div><p>All team members can read this permitted excerpt. Helpers reference their own department’s sources. No live company integrations are connected.</p>`)})}function renderSources(inTab=false){const h='<div class="content-panel"><div class="eyebrow">DEPARTMENT KNOWLEDGE</div><h3 style="margin-top:12px">Shared facts. Department perspectives.</h3><p>These sample excerpts are safe to share across the room. Helpers use evidence associated with their own department.</p>'+state.sources.map(s=>`<button class="source-card" data-source="${s.id}" style="width:100%;background:white;text-align:left"><strong>▧ ${esc(s.title)}</strong><small>${esc(s.department)} · Sample data</small></button>`).join('')+'</div>';$(inTab?'#tab-content':'#detail').innerHTML=h;bindSources()}
function newRequest(){if(!user)return identity();modal('<h2>Start a live negotiation</h2><p>Invite people from each department. Their helpers will support the discussion.</p><form id="new-form"><label for="title">Title</label><input id="title" required maxlength="120"><label for="description">Shared outcome & constraints</label><textarea id="description" required maxlength="2000"></textarea><p>Helpers currently use the SSO pilot case study. Custom requests retain their context but require human validation of the sample proposal.</p><button class="primary">Create room →</button></form>');$('#new-form').onsubmit=async e=>{e.preventDefault();try{const result=await api('rooms',{title:$('#title').value,description:$('#description').value});selected=result.roomId;location.hash=selected;view='requests';tab='conversation';$('#modal').close();await refresh()}catch(e){toast(e.message)}}}
$('.modal-close').onclick=()=>$('#modal').close();$('#new-request').onclick=newRequest;$('#reset').onclick=identity;$('#how').onclick=()=>modal('<h2>Teams negotiate together.</h2><p>1. Join the same room as Business or Engineering.<br>2. Ask Maya or Theo for help with your department’s evidence.<br>3. Post context, or choose “Redirect helpers” to revise the draft.<br>4. One member from each department approves the same revision.</p><div class="boundary">Live collaboration is real. Helpers are deterministic demo assistants, not live AI models. Department identity is self-declared. Use separate browsers or private windows to demo two teammates.</div>');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{draft=$('#comment')?.value||draft;view=b.dataset.view;render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#filter').onclick=()=>{filter=filter==='active'?'all':'active';render()};document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{const d=b.dataset.team;modal(`<div class="eyebrow">${d} DEPARTMENT</div><h2>${d==='Business'?'Maya':'Theo'} is your team’s helper.</h2><p>${d==='Business'?'Helps people reason about customer needs, commercial goals, and acceptance criteria.':'Helps people reason about capacity, implementation work, and delivery tradeoffs.'}</p><p>Join a negotiation as a department member to ask for support. Helpers advise; team members contribute context, redirect work, and approve agreements.</p>`) });$('#activity').onclick=()=>{tab='conversation';view='requests';render()};window.addEventListener('hashchange',()=>{selected=location.hash.slice(1);draft='';render()});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();newRequest()}});
try{await refresh();const events=new EventSource('/api/events');events.onmessage=e=>{draft=$('#comment')?.value||draft;const mode=$('#message-mode')?.value;state=JSON.parse(e.data);render();if(mode&&$('#message-mode'))$('#message-mode').value=mode;$('.workspace-sub').innerHTML='<i></i> Live workspace connected'};events.onerror=()=>{$('.workspace-sub').textContent='Reconnecting to shared workspace…'};if(!user)identity()}catch(e){$('#detail').innerHTML='<div class="empty">Start the shared server with <strong>npm run dev</strong>. This version needs a Node.js backend; static hosting alone does not support live rooms.</div>';toast('Cannot reach the shared server.')}
